// Package artifact provides bounded, tenant-scoped storage for sanitized IVP
// report artifacts. Object keys are generated by the service and are never
// accepted from callers.
package artifact

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/google/uuid"
)

const (
	DefaultMaxBytes int64 = 16 << 20
	MaxAllowedBytes int64 = 64 << 20
)

var objectKeyPattern = regexp.MustCompile(`^[0-9a-f-]{36}/[0-9a-f-]{36}$`)

type Metadata struct {
	Key       string
	MediaType string
	Size      int64
	SHA256    string
}

// Store implementations must enforce maxBytes even when the input has no
// Content-Length and must scope objects beneath the supplied opaque key.
type Store interface {
	Put(context.Context, string, string, io.Reader, int64) (Metadata, error)
	Open(context.Context, string) (io.ReadCloser, error)
	Delete(context.Context, string) error
}

// TenantKey returns an opaque storage key that cannot contain user-controlled
// path segments.
func TenantKey(tenantID, artifactID uuid.UUID) string {
	return tenantID.String() + "/" + artifactID.String()
}

func ValidateKey(key string) error {
	if !objectKeyPattern.MatchString(key) {
		return errors.New("invalid artifact object key")
	}
	return nil
}

// FileStore is the single-node filesystem implementation. The root directory
// should be a dedicated volume with restrictive ownership and permissions.
type FileStore struct{ root string }

func NewFileStore(root string) (*FileStore, error) {
	if strings.TrimSpace(root) == "" {
		return nil, errors.New("artifact directory is required")
	}
	abs, err := filepath.Abs(root)
	if err != nil {
		return nil, err
	}
	if err := os.MkdirAll(abs, 0o700); err != nil {
		return nil, fmt.Errorf("create artifact directory: %w", err)
	}
	resolvedRoot, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return nil, fmt.Errorf("resolve artifact directory: %w", err)
	}
	return &FileStore{root: resolvedRoot}, nil
}

func (s *FileStore) objectPath(key string) (string, error) {
	if s == nil || s.root == "" {
		return "", errors.New("artifact store is unavailable")
	}
	if err := ValidateKey(key); err != nil {
		return "", err
	}
	path := filepath.Join(s.root, filepath.FromSlash(key))
	rel, err := filepath.Rel(s.root, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
		return "", errors.New("artifact path escapes storage root")
	}
	return path, nil
}

func (s *FileStore) Put(ctx context.Context, key, mediaType string, src io.Reader, maxBytes int64) (Metadata, error) {
	var meta Metadata
	path, err := s.objectPath(key)
	if err != nil {
		return meta, err
	}
	if src == nil || maxBytes <= 0 || maxBytes > MaxAllowedBytes {
		return meta, errors.New("artifact source and size bound between 1 byte and 64 MiB are required")
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return meta, fmt.Errorf("create tenant artifact directory: %w", err)
	}
	if err := s.verifyWithinRoot(filepath.Dir(path)); err != nil {
		return meta, err
	}
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return meta, fmt.Errorf("create artifact object: %w", err)
	}
	ok := false
	defer func() {
		_ = file.Close()
		if !ok {
			_ = os.Remove(path)
		}
	}()
	hash := sha256.New()
	limited := &contextReader{ctx: ctx, r: io.LimitReader(src, maxBytes+1)}
	size, err := io.Copy(io.MultiWriter(file, hash), limited)
	if err != nil {
		return meta, err
	}
	if size > maxBytes {
		return meta, errors.New("artifact exceeds configured size limit")
	}
	if err := file.Sync(); err != nil {
		return meta, fmt.Errorf("sync artifact object: %w", err)
	}
	if err := file.Close(); err != nil {
		return meta, err
	}
	ok = true
	return Metadata{Key: key, MediaType: mediaType, Size: size, SHA256: hex.EncodeToString(hash.Sum(nil))}, nil
}

func (s *FileStore) Open(ctx context.Context, key string) (io.ReadCloser, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	path, err := s.objectPath(key)
	if err != nil {
		return nil, err
	}
	if err := s.verifyWithinRoot(path); err != nil {
		return nil, err
	}
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	return f, nil
}

func (s *FileStore) verifyWithinRoot(path string) error {
	resolved, err := filepath.EvalSymlinks(path)
	if err != nil {
		return err
	}
	rel, err := filepath.Rel(s.root, resolved)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
		return errors.New("artifact path resolves outside storage root")
	}
	return nil
}

func (s *FileStore) Delete(ctx context.Context, key string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	path, err := s.objectPath(key)
	if err != nil {
		return err
	}
	err = os.Remove(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	return err
}

func NewID() (uuid.UUID, error) {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return uuid.Nil, err
	}
	return uuid.UUID(b), nil
}

func Expiry(now time.Time, retention time.Duration) (time.Time, error) {
	if now.IsZero() || retention <= 0 || retention > 365*24*time.Hour {
		return time.Time{}, errors.New("artifact retention must be positive and at most 365 days")
	}
	return now.UTC().Add(retention), nil
}

type contextReader struct {
	ctx context.Context
	r   io.Reader
}

func (r *contextReader) Read(p []byte) (int, error) {
	if err := r.ctx.Err(); err != nil {
		return 0, err
	}
	return r.r.Read(p)
}
